PTVC_SETNAME[2] = { "X\221ch T\239ng ", "Th\184i \202t ", "Th\171ng Thi\170n ", "H\229ng Qu\169n " }
PTVC_SETNAME[3] = { "B\184o Th\199n ", "Gi\184c Th\243 ", "Lam \167i\170u ", "Kh\184ng Long " }
PTVC_PARTNAME = {}
