PTVC_PARTNAME[2] = { "\167\185o B\181o", "L\253", "C\169n", "Qu\184n", "L\214nh" }
PTVC_PARTNAME[3] = { "H\233 Gi\184p", "Ngoa", "Y\170u \167\184i", "Tr\244", "K\213t" }

function PTVC_PieceName(r, k)
	local t = GetPlayerType()
	if not t or t < 0 or t > 2 then t = 0 end
	local idx = 2
	if r == 9 then idx = 3 end
	return PTVC_SETNAME[t + 1][idx] .. PTVC_PARTNAME[t + 1][k]
end

-- give piece k of the due rank item, then the normal reward; nil if the bag is full (nothing lost)
function PTVC_RankItem(k)
	local r = PTVC_RankItemDue()
	if not r or not PTVC_RewardReady() then return nil end
	if r == 9 and (k < 2 or k > 4) then return nil end
	if k < 1 or k > 5 then return nil end
	local t = GetPlayerType()
	if not t or t < 0 or t > 2 then return nil end
	local lvi = 5
	if r == 9 then lvi = 7 end
	local it = AddNormalItem(0, PTVC_PIECE[k], t + 6, lvi, 0, 0, 0)
	if not it or it <= 0 then return nil end
	AddGlobalCountNews("<color=green>" .. GetName() .. format("<color> \174\188ng c\202p chi\213n tr\173\234ng t\168ng %d, \174\173\238c ban th\173\235ng <color=green>", r + 1) .. PTVC_PieceName(r, k) .. "<color>.", 2)
	PTVC_Reward()
	return 1
end

